import java.util.*;
import java.io.*;

public class Main {
    static long[] lsc = new long[62], rsc = new long[62], rsc2 = new long[62];
    static String s;
    static Map<Pair<Long, Integer>, Long> nm, mm;
    static final long INF = (long)1e18;

    static class Pair<K, V> {
        K first;
        V second;

        Pair(K first, V second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Pair))
                return false;
            Pair<?, ?> p = (Pair<?, ?>) o;
            return Objects.equals(first, p.first) && Objects.equals(second, p.second);
        }

        @Override
        public int hashCode() {
            return Objects.hash(first, second);
        }
    }

    static long comb(int n, int k) {
        if (n < k || k < 0) return 0;
        long rez = 1;
        for (int i = 0; i < k; i++) {
            rez = rez * (n - i) / (i + 1);
        }
        return rez;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        st = new StringTokenizer(br.readLine());
        int r = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());

        int n = 2 * (r + c);

        s = br.readLine().trim();

        lsc[2 * r - 1] = 1;
        for (int i = 2 * r; i < n; i++) {
            lsc[i] = lsc[i - 1] * i / (i - 2 * r + 1);
        }

        for (int i = 0; i <= n; i++) {
            rsc[i] = comb(i, r);
            rsc2[i] = comb(i, r - 1);
        }

        long nsum = rsc[n / 2] * rsc[n / 2];

        int cnta = 0, cntb = 0;
        long msum = nsum;
        for (int i = n - 1; i >= 0; i--) {
            int ok;
            if (msum > 0)
                ok = 1;
            else
                ok = 0;
            if (cntb == n / 2)
                ok = 1;
            if (cnta == n / 2)
                ok = 0;

            if (ok == 1) {
                cnta++;
                msum = msum - rsc2[n / 2 - cnta] * rsc[n / 2 - cntb];
            } else {
                cntb++;
                msum = msum + rsc2[n / 2 - cntb] * rsc[n / 2 - cnta];
            }
        }
        msum = Math.max(msum, -msum);

        mm = new HashMap<>();
        mm.put(new Pair<>(0L, 0), 1L);
        for (int i = n - 1; i >= 2 * r - 1; i--) {
            nm = new HashMap<>();
            for (Map.Entry<Pair<Long, Integer>, Long> entry : mm.entrySet()) {
                long sum = entry.getKey().first;
                int cnt = entry.getKey().second;
                long ncnt = entry.getValue();

                int ast = n / 2 - cnt;
                int bst = i + 1 - ast;

                long asum = sum + rsc2[ast - 1] * rsc[bst];
                long bsum = sum - rsc2[bst - 1] * rsc[ast];

                if (s.charAt(i) == 'A') {
                    Pair<Long, Integer> keyAs = new Pair<>(asum, cnt + 1);
                    nm.put(keyAs, nm.getOrDefault(keyAs, 0L) + ncnt);
                    Pair<Long, Integer> keyB = new Pair<>(bsum, cnt);
                    nm.put(keyB, nm.getOrDefault(keyB, 0L));
                } else if (s.charAt(i) == 'B') {
                    Pair<Long, Integer> keyAs = new Pair<>(asum, cnt + 1);
                    nm.put(keyAs, nm.getOrDefault(keyAs, 0L));
                    Pair<Long, Integer> keyB = new Pair<>(bsum, cnt);
                    nm.put(keyB, nm.getOrDefault(keyB, 0L) + ncnt);
                } else {
                    Pair<Long, Integer> keyAs = new Pair<>(asum, cnt + 1);
                    nm.put(keyAs, nm.getOrDefault(keyAs, 0L) + ncnt);
                    Pair<Long, Integer> keyB = new Pair<>(bsum, cnt);
                    nm.put(keyB, nm.getOrDefault(keyB, 0L) + ncnt);
                }
            }
            long newNsum = nsum - lsc[i];
            nsum = newNsum;

            mm.clear();
            for (Map.Entry<Pair<Long, Integer>, Long> entry : nm.entrySet()) {
                long sum = entry.getKey().first;
                int cnt = entry.getKey().second;
                long ncnt = entry.getValue();

                int ast = n / 2 - cnt;
                int bst = i - ast;

                if (cnt > n / 2 || n - i - cnt > n / 2)
                    continue;
                if (sum < -msum - rsc[ast] * rsc[bst] || sum > msum + rsc[ast] * rsc[bst])
                    continue;
                Pair<Long, Integer> key = new Pair<>(sum, cnt);
                mm.put(key, mm.getOrDefault(key, 0L) + ncnt);
            }
        }

        long bsum = (long)1e18;
        for (Map.Entry<Pair<Long, Integer>, Long> entry : mm.entrySet()) {
            long sum = entry.getKey().first;
            bsum = Math.min(bsum, Math.max(sum, -sum));
        }

        long rasp = 0;
        for (Map.Entry<Pair<Long, Integer>, Long> entry : mm.entrySet()) {
            long sum = entry.getKey().first;
            long ncnt = entry.getValue();
            int cnt = entry.getKey().second;
            if (sum == bsum || sum == -bsum) {
                int sem = 0;
                for (int i = 0; i < 2 * r - 1; i++) {
                    if (s.charAt(i) == '?') {
                        sem++;
                    } else if (s.charAt(i) == 'A') {
                        cnt++;
                    }
                }
                long ncnt2 = ncnt * comb(sem, n / 2 - cnt);
                rasp += ncnt2;
            }
        }

        System.out.println(rasp);
    }
}
